/**  Server -> Client (`/api/v1/client/ws`) message. */
export type ServerWsMessage = 
/**
 *  A batch of incremental events (the replay right after connecting and the
 *  realtime delivery afterwards).
 */
{ op: "event_batch"; 
/**  Events (ascending `node_seq`) */
events: SessionEventEnvelope[]; 
/**  Cursor of the source store (passed as `since_cursor` when reconnecting) */
cursor: number } | 
/**  An ephemeral chunk produced while streaming (never persisted). */
{ op: "live_stream_delta"; 
/**  Target session ID */
session_id: SessionId; 
/**  The delta body */
delta: StreamDeltaPayload } | 
/**
 *  A progress log line of ephemeral VM bootstrapping (`stderr`) (ephemeral).
 * 
 *  Bootstrapping happens before the ephemeral node's `node.db` exists, so it is
 *  streamed directly from the central server instead of being persisted in the
 *  event log.
 */
{ op: "bootstrap_log"; 
/**  Target session ID */
session_id: SessionId; 
/**  A single log line */
line: string } | 
/**  Result of a command (correlated back to the requesting client). */
{ op: "command_result"; 
/**  Correlation ID */
command_id: CommandId; 
/**  Whether it succeeded */
success: boolean; 
/**  Structured error on failure */
error?: ErrorInfo | null; 
/**  Target session ID (optional) */
session_id: SessionId | null } | 
/**  Synchronization state notification (drives the sync badge in the UI). */
{ op: "system_status"; 
/**  Whether the central server is connected (when connected to a local node) */
central_connected: boolean; 
/**  Number of unsynced outbox events */
unsynced_event_count: number; 
/**  Last synchronization time (Unix epoch ms) */
last_synced_at: number | null } | 
/**  Error notification. */
{ op: "error"; 
/**  Structured error */
error: ErrorInfo } | 
/**  Response to `Ping` */
{ op: "pong" };

/**
 *  `POST /api/v1/sessions/:id/archive` request.
 * 
 *  Archiving only hides or restores the session in the listing; the event log is
 *  kept (erasing conversation bodies is done by `DELETE /api/v1/sessions/:id`).
 */
export type SessionArchiveRequest = {
	/**  `true` = archive, `false` = restore */
	archived: boolean,
};

/**  `POST /api/v1/sessions/:id/archive` response. */
export type SessionArchiveResponse = {
	/**  Target session ID */
	session_id: SessionId,
	/**  Archive time (Unix epoch ms). `None` when restored */
	archived_at: number | null,
};

/**  Session control action (`ControlSession` command). */
export type SessionControlAction = 
/**  Switch mode (`plan` / `code` etc.) */
{ action: "set_mode"; 
/**  ID of the mode to switch to */
mode_id: string } | 
/**  Change a configuration value (model selection etc.) */
{ action: "set_config"; 
/**  Configuration key */
key: string; 
/**  New value */
value: ConfigOptionValue } | 
/**  Change the approval policy (ask / auto-approve) */
{ action: "set_permission_policy"; 
/**  New policy */
policy: string } | 
/**  Interrupt the current turn */
{ action: "cancel" } | 
/**  Terminate the session entirely */
{ action: "kill" };

/**
 *  A batch of events with a cursor (shared by Client WS delivery and the history API).
 * 
 *  `cursor` is the ingestion order of the **source store** (`node.db` /
 *  `server.db`). Clients persist the `cursor` of the last batch they received and
 *  pass it as `Subscribe { since_cursor }` when reconnecting. A `cursor` is only
 *  meaningful for the store it came from.
 */
export type SessionEventBatch = {
	/**  Events (ascending `node_seq`) */
	events: SessionEventEnvelope[],
	/**  Cursor of the source store at the time of this batch */
	cursor: number,
};

/**  Envelope of a session event (the unit of persistence and synchronization). */
export type SessionEventEnvelope = {
	/**  Event ID (**UUID v7**). Used for idempotent application and deduplication. */
	event_id: EventId,
	/**  Session ID (**UUID v7**). */
	session_id: SessionId,
	/**
	 *  Sequence number inside the session (`1, 2, 3...`). **Only the running node
	 *  assigns it** and there are no gaps. The logical order inside a session is
	 *  always defined by this value.
	 */
	node_seq: number,
	/**  Creation time according to the node's local clock (Unix epoch ms). */
	created_at: number,
	/**  The event body. */
	payload: UnifiedEventPayload,
};

/**  Specification of a context fork. */
export type SessionForkSpec = {
	/**  Source session ID */
	from_session_id: SessionId,
};

/**  ID of a session (UUID v7 assigned by the running node / server). */
export type SessionId = string;

/**  `GET /api/v1/sessions` response. */
export type SessionListResponse = {
	/**  Sessions (newest update first) */
	sessions: SessionSummary[],
};

/**  Session status (same values as `sessions.status`). */
export type SessionStatus = 
/**  Provisioning an ephemeral VM */
"provisioning" | 
/**  Bootstrapping (automatically installing tools) */
"bootstrapping" | 
/**  Idle (waiting for a prompt) */
"idle" | 
/**  Running a turn */
"running" | 
/**  Waiting for permission approval */
"waiting_permission" | 
/**  Waiting for an elicitation (question / structured input) answer */
"waiting_input" | 
/**  Stopped */
"stopped" | 
/**  Error */
"error";

/**
 *  Aggregated session type used in API responses (built from a `sessions` row).
 * 
 *  On the hub side it is produced from the projection obtained by applying
 *  events. Both the local node and the central server return this same type.
 */
export type SessionSummary = {
	/**  Session ID (UUID v7) */
	session_id: SessionId,
	/**  Logical project ID (e.g. `github.com/nazo6/flexagent`) */
	project_id: ProjectId,
	/**  ID of the node running the session */
	node_id: NodeId,
	/**  Working directory (including the worktree path) */
	local_path: string,
	/**  Snapshot taken at start-up (live values come from the worktree API) */
	git_branch: string | null,
	/**  Whether it runs inside a worktree */
	is_worktree: boolean,
	/**  Agent ID (`opencode2` / `antigravity-acp` etc.) */
	agent_id: string,
	/**  Session ID inside the agent (fixed by the `SessionAgentBound` event) */
	agent_session_id: string | null,
	/**  Session ID this session was forked from */
	parent_session_id: SessionId | null,
	/**  Session title */
	title: string,
	/**  Session status */
	status: SessionStatus,
	/**  Current ACP SessionMode (e.g. `code`, `plan`) */
	current_mode: string | null,
	/**  Approval policy (`ask` / `auto_allow_all`) */
	permission_policy?: string,
	/**
	 *  Latest context usage and accumulated cost (projection of the `UsageUpdated` event).
	 * 
	 *  `None` means nothing has been received yet (including the case where the
	 *  agent never sends `usage_update`).
	 */
	usage: SessionUsage | null,
	/**  Latest persisted `node_seq` (node) / highest `node_seq` applied to the projection (hub) */
	last_node_seq: number,
	/**  Whether the agent supports ACP-native `session/fork` + `session/load` */
	fork_supported?: boolean,
	/**  Creation time (Unix epoch ms) */
	created_at: number,
	/**  Last update time (Unix epoch ms) */
	updated_at: number,
	/**
	 *  Archive time (Unix epoch ms). `None` means not archived.
	 * 
	 *  Archived sessions are excluded from the default listing (they are only
	 *  returned when `include_archived` is set).
	 */
	archived_at: number | null,
};

/**
 *  Context usage and accumulated cost of a session
 *  (the `usage_update` of ACP `session/update`).
 */
export type SessionUsage = {
	/**  Number of tokens currently occupying the context */
	used_tokens: number,
	/**  Total context window size (in tokens) */
	context_size: number,
	/**  Accumulated cost (only when reported by the agent) */
	cost: UsageCost | null,
};

/**  A read-only bootstrap value together with its origin. */
export type SourcedValue<T> = {
	/**  The effective value */
	value: T,
	/**  Which layer supplied the value */
	source: string,
	/**  Environment variable name / config.toml key / CLI flag (when known) */
	source_detail: string | null,
};

/**
 *  Ephemeral chunk produced while streaming.
 * 
 *  It is never persisted to the DB and never resent (exclusive to
 *  `LiveStreamDelta`). Once the final event (`AgentMessage` etc.) arrives, the
 *  client replaces the chunk with the committed representation.
 */
export type StreamDeltaPayload = 
/**  Incremental text of an agent reply message */
{ delta_type: "agent_message_delta"; 
/**  Message ID (corresponds to `AgentMessage.message_id`) */
message_id: string; 
/**  Appended text */
text_delta: string } | 
/**  Incremental text of the reasoning process */
{ delta_type: "agent_thought_delta"; 
/**  Thought ID (corresponds to `AgentThought.thought_id`) */
thought_id: string; 
/**  Appended text */
text_delta: string } | 
/**  Progress update of a tool call */
{ delta_type: "tool_call_progress"; 
/**  Tool call ID */
tool_call_id: string; 
/**  Updated status */
status: string; 
/**  Output delta (optional) */
raw_output_delta: string | null } | 
/**  Output delta of an ACP terminal/* */
{ delta_type: "terminal_output_delta"; 
/**  Terminal ID */
terminal_id: string; 
/**  Output bytes (Base64) */
data_b64: string };

/**  `GET /api/v1/system/info` response. */
export type SystemInfoResponse = {
	/**  Kind of endpoint */
	role: ConnectionRole,
	/**  fxg binary version */
	version: string,
	/**  VAPID public key for Web Push (central server only) */
	vapid_public_key: string | null,
	/**  Number of unsynced outbox events (local node only) */
	unsynced_event_count: number | null,
	/**  WebSocket connection state to the central server (local node only) */
	central_connected: boolean | null,
};

/**
 *  Reasons an agent stopped a turn that should be surfaced to the user.
 * 
 *  Of the ACP `StopReason` values, `EndTurn` / `Cancelled` end the turn normally
 *  and are not turned into an event (see `UnifiedEventPayload::TurnEnded`).
 */
export type TurnStopReason = 
/**  Cut off after reaching the maximum number of tokens */
"max_tokens" | 
/**  Cut off after reaching the per-turn limit of agent requests */
"max_turn_requests" | 
/**  The agent refused to continue (Refusal) */
"refusal";

/**
 *  The body of a normalized session event.
 * 
 *  Based on the event model of ACP (`agent-client-protocol-schema`), with
 *  terminal output and permission resolution events merged in.
 */
export type UnifiedEventPayload = 
/**
 *  The first event right after a session is created (`node_seq = 1`).
 * 
 *  The source of the hub-side `sessions` projection. No separate metadata
 *  synchronization path exists.
 */
{ type: "session_created"; data: {
	/**
	 *  ID of the running node. The running node fills in its own ID so that
	 *  the hub-side projection can be rebuilt entirely from the event log.
	 */
	node_id: NodeId,
	/**  Logical project ID */
	project_id: ProjectId,
	/**  Project display name (used by the hub to create unknown projects) */
	project_name: string,
	/**  Working directory (including the worktree path) */
	local_path: string,
	/**  Git branch at start-up (a snapshot) */
	git_branch: string | null,
	/**  Whether it runs inside a worktree */
	is_worktree: boolean,
	/**  Agent ID */
	agent_id: string,
	/**  Session ID this session was forked from */
	parent_session_id: SessionId | null,
	/**  Initial title */
	title: string,
} } | 
/**
 *  Session title change (a rename from the UI/CLI; emitted once the command
 *  reaches the running node).
 */
{ type: "session_title_changed"; data: {
	/**  New title */
	title: string,
} } | 
/**  The `agent_session_id` becomes known, e.g. when the ACP session is established. */
{ type: "session_agent_bound"; data: {
	/**  Session ID inside the agent */
	agent_session_id: string,
} } | 
/**  A prompt submitted by the user (including slash commands). */
{ type: "user_message"; data: {
	/**  Prompt body */
	text: string,
	/**  Attached files */
	attachments: AttachmentMeta[],
	/**  Source (`cli` / `web` / `android` / `resume`) */
	client_source: string,
} } | 
/**
 *  A reply message from the agent.
 * 
 *  While streaming it is delivered as `LiveStreamDelta`, and only the final
 *  event with `is_complete = true` is persisted when the turn ends.
 */
{ type: "agent_message"; data: {
	/**  Message ID (corresponds to `StreamDeltaPayload::AgentMessageDelta`) */
	message_id: string,
	/**  Body text */
	text: string,
	/**  Whether it is complete (only `true` is persisted) */
	is_complete: boolean,
} } | 
/**
 *  The reasoning process of the agent (thinking).
 * 
 *  Like `AgentMessage`, only the final event with `is_complete = true` is persisted.
 */
{ type: "agent_thought"; data: {
	/**  Thought ID (corresponds to `StreamDeltaPayload::AgentThoughtDelta`) */
	thought_id: string,
	/**  Body text */
	text: string,
	/**  Whether it is complete */
	is_complete: boolean,
} } | 
/**
 *  A tool call and its state, including file diffs.
 * 
 *  State updates are expressed by appending events with the same
 *  `tool_call_id` (the `tool_update` event was removed).
 */
{ type: "tool_call"; data: {
	/**  Tool call ID */
	tool_call_id: string,
	/**  Display title */
	title: string,
	/**  Kind (`read` / `edit` / `execute` / `search` / `other`) */
	kind: string,
	/**  Status (`pending` / `in_progress` / `completed` / `failed`) */
	status: string,
	/**  Affected file paths */
	locations: string[],
	/**  Unified diff / before-after of a file change */
	diff: FileDiff | null,
	/**  Raw output (optional) */
	raw_output: string | null,
} } | 
/**  The execution plan of the agent (ACP Plan). */
{ type: "plan_update"; data: {
	/**  Plan entries */
	entries: PlanEntry[],
} } | 
/**
 *  A permission approval request from the agent
 *  (ACP `session/request_permission`).
 */
{ type: "permission_request"; data: {
	/**  ACP request id */
	request_id: string,
	/**  Tool name (e.g. `terminal/create`) */
	tool_name: string,
	/**  Summary (e.g. `Run command: cargo test`) */
	summary: string,
	/**  Options (e.g. `allow_once` / `allow_always` / `reject`) */
	options: PermissionOption[],
	/**  Arguments and diff details */
	details: RawJson,
} } | 
/**
 *  The outcome of a permission request.
 * 
 *  `fxg daemon` emits this event at the same time as it answers the agent, so
 *  that approval dialogs in other clients close automatically. Second and
 *  later answers are dropped per `request_id` and `ALREADY_RESOLVED` is returned.
 */
{ type: "permission_resolved"; data: {
	/**  ACP request id */
	request_id: string,
	/**  The selected `option_id` */
	selected_option_id: string,
	/**  Who resolved it (`cli` / `web` / `android_push`) */
	resolved_by: string,
} } | 
/**
 *  A structured input request from the agent (ACP `elicitation/create`).
 * 
 *  The agent's "question" tool arrives as this event and the UI / CLI builds
 *  an answer form from `requested_schema`. Answers are appended as
 *  [`UnifiedEventPayload::ElicitationResolved`]
 *  (Phase 1 supports form mode only).
 */
{ type: "elicitation_request"; data: {
	/**  ACP elicitation id */
	elicitation_id: string,
	/**  Message shown to the user */
	message: string,
	/**  Request mode (`form` / `url`. Phase 1 supports `form` only) */
	mode: string,
	/**  JSON Schema of the request in form mode (`requestedSchema`) */
	requested_schema: ElicitationSchema,
	/**  Related tool call ID (optional) */
	tool_call_id: string | null,
} } | 
/**  The outcome of a structured input request (accept / decline / cancel). */
{ type: "elicitation_resolved"; data: {
	/**  ACP elicitation id */
	elicitation_id: string,
	/**  The user's response action */
	action: ElicitationAction,
	/**  Answer content for `accept` (`None` on decline / cancel) */
	content: { [key in string]: ElicitationValue } | null,
	/**  Who resolved it (`cli` / `web` / `android_push`) */
	resolved_by: string,
} } | 
/**
 *  A change of the session's archive state (hidden from / restored to the list).
 * 
 *  Archiving is a reversible visibility flag; the event log and conversation
 *  content are kept (a permanent erase is
 *  [`UnifiedEventPayload::SessionDeleted`]).
 */
{ type: "session_archived"; data: {
	/**  `true` = archived, `false` = restored */
	archived: boolean,
} } | 
/**  Change of the session approval policy (`ask` / `auto_allow_all`). */
{ type: "session_permission_policy_changed"; data: {
	/**  New policy */
	policy: string,
} } | 
/**
 *  Deletion of a session (tombstone).
 * 
 *  Applying it purges the bodies of all events before it (irreversible). The
 *  event itself remains as a tombstone so that the deletion propagates through
 *  the outbox / resync and references from forked sessions stay consistent.
 */
{ type: "session_deleted"; data: Record<string, never> } | 
/**
 *  An output chunk of ACP `terminal/*` or a PTY (persisted).
 * 
 *  It is, however, excluded from the FTS5 `searchable_text` (binary data).
 */
{ type: "terminal_output"; data: {
	/**  Terminal ID */
	terminal_id: string,
	/**  Executed command */
	command: string,
	/**  Raw bytes including ANSI escapes (Base64) */
	data_b64: string,
	/**  Exit code (once execution finished) */
	exit_code: number | null,
} } | 
/**
 *  A stdin write to an interactive command (Web UI -> agent PTY).
 * 
 *  Keystrokes are ephemeral and are not persisted to the event log (raw
 *  delivery through the PTY WS is also possible). See
 *  [`UnifiedEventPayload::is_persistable`].
 */
{ type: "terminal_input"; data: {
	/**  Terminal ID */
	terminal_id: string,
	/**  User keystrokes (Base64) */
	data_b64: string,
} } | 
/**
 *  Notification of updated modes, slash commands and configuration (persisted).
 * 
 *  The update source of the hub-side `sessions.current_mode` /
 *  `available_modes_json` / `available_commands_json` / `config_options_json`
 *  projections.
 */
{ type: "capabilities_updated"; data: {
	/**  Current mode (`None` keeps the existing value) */
	current_mode: string | null,
	/**  Selectable modes */
	available_modes: ModeInfo[],
	/**  Available slash commands */
	available_commands: CommandInfo[],
	/**  Configuration entries (model selection etc.) */
	config_options: ConfigOptionInfo[],
	/**
	 *  Whether the agent supports ACP-native `session/fork` + `session/load`.
	 *  `None` keeps the existing value (events recorded before this field
	 *  existed).
	 */
	fork_supported?: boolean | null,
} } | 
/**  A progress log line of ephemeral VM provisioning / automatic tool setup (`stderr`). */
{ type: "bootstrap_log"; data: {
	/**  A single log line */
	line: string,
} } | 
/**
 *  An update of the context usage and accumulated cost (the `usage_update` of
 *  ACP `session/update`). The update source of the hub-side `sessions.usage_json`
 *  projection.
 */
{ type: "usage_updated"; data: {
	/**  Number of tokens currently occupying the context */
	used_tokens: number,
	/**  Total context window size (in tokens) */
	context_size: number,
	/**  Accumulated cost (only when reported by the agent) */
	cost: UsageCost | null,
} } | 
/**
 *  A turn was cut off for a reason other than normal completion (ACP `StopReason`).
 * 
 *  `EndTurn` / `Cancelled` end the turn normally and are not turned into an
 *  event. The UI / CLI shows this as a system line in the timeline and
 *  derives its label from `reason` (no message text is carried).
 */
{ type: "turn_ended"; data: {
	/**  Why the turn was cut off */
	reason: TurnStopReason,
} } | 
/**
 *  Progress of context compaction (persisted).
 * 
 *  Normalizes `session.compaction.started` / `.ended` of the `opencode2`
 *  bridge (started with `/compact` or `ControlSession(Compact)`. A compaction
 *  runs as one turn, so `StatusChanged` separately updates the running
 *  indicator). Streaming of the summary body (`session.compaction.delta`) is
 *  ephemeral and not turned into events (the summary stays in the agent's
 *  history).
 */
{ type: "compaction_updated"; data: {
	/**  Progress status */
	status: CompactionStatus,
	/**  Extra information such as the failure reason (optional) */
	detail: string | null,
} } | 
/**
 *  A change of the session status. The update source of the hub-side
 *  `sessions.status` projection.
 */
{ type: "status_changed"; data: {
	/**  New status */
	status: SessionStatus,
	/**  Message for the error case */
	error_message: string | null,
} };

/**  `PATCH /api/v1/settings/agents` request. */
export type UpdateAgentSettingsRequest = {
	/**  Default agent ID */
	default_agent: string | null,
	/**  ACP Registry URL */
	registry_url: string | null,
	/**  Registry cache TTL in seconds */
	registry_cache_ttl_secs: number | null,
	/**  Agent name aliases */
	aliases: { [key in string]: string },
	/**  Revision the client observed (`REVISION_MISMATCH` on conflict) */
	expected_revision: number,
};

/**  `PATCH /api/v1/settings/node` request. */
export type UpdateNodeSettingsRequest = {
	/**  Display name */
	name: string,
	/**  Remote PTY policy */
	allow_remote_pty: boolean,
	/**  Default project scan directories */
	project_scan_dirs: string[],
	/**  Tray residency */
	tray: boolean | null,
	/**  Revision the client observed (`REVISION_MISMATCH` on conflict) */
	expected_revision: number,
};

/**  `PUT /api/v1/projects/{project_id}/profile` request. */
export type UpdateProjectProfileRequest = {
	/**  Setup commands */
	bootstrap_setup: string[],
	/**  Non-secret environment variables */
	bootstrap_env: { [key in string]: string },
	/**  Revision the client observed (`REVISION_MISMATCH` on conflict) */
	expected_revision: number,
};

/**  `PATCH /api/v1/settings/server` request. */
export type UpdateServerSettingsRequest = {
	/**  Web Push contact claim */
	vapid_subject: string | null,
	/**  Per-host Git credential provider */
	git_credentials: { [key in string]: GitCredentialConfig },
	/**  Revision the client observed (`REVISION_MISMATCH` on conflict) */
	expected_revision: number,
};

/**  `PUT /api/v1/secrets/{secret_id}` request (write-only). */
export type UpsertSecretRequest = {
	/**  Optional description or note */
	description: string | null,
	/**  The plaintext value. Never echoed back in a response or written to logs. */
	value: string,
};

/**  Accumulated session cost (ACP `Cost`). */
export type UsageCost = {
	/**  Accumulated cost amount */
	amount: number,
	/**  ISO 4217 currency code (e.g. `USD`) */
	currency: string,
};

/**  Non-fatal warning attached to a successful / partially successful response. */
export type WarningInfo = {
	/**  Structured warning code (same vocabulary as [`ErrorCode`]) */
	code: ErrorCode,
	/**  English human-readable fallback message */
	message: string,
	/**  Technical details */
	details?: RawJson | null,
	/**  Recovery actions the client can offer */
	recovery?: RecoveryAction[],
};

/**  Result of fetching the diff of a git working tree (`GET /api/v1/sessions/:id/diff`). */
export type WorkspaceDiffResponse = {
	/**  Scope of the fetched diff */
	scope: DiffScope,
	/**  Base branch used for the comparison (set for `BranchBase`) */
	base_branch: string | null,
	/**  Current HEAD commit */
	head_commit: string,
	/**  Diff per changed file */
	files: FileDiff[],
};

/**  Worktree operation action (`ManageWorktree` command). */
export type WorktreeAction = 
/**  Create a new worktree (`git worktree add -b <branch> <path> <base>`) */
{ action: "add"; 
/**  Name of the branch to create */
branch: string; 
/**  Base branch (defaults to the current HEAD) */
base_branch: string | null } | 
/**  Remove a worktree (`git worktree remove`) */
{ action: "remove"; 
/**  Path to remove */
path: string; 
/**  Whether to remove even if there are uncommitted changes */
force: boolean } | 
/**  Clean up the administrative data of deleted worktrees (`git worktree prune`) */
{ action: "prune" };

/**  Information about a git worktree (`GET /api/v1/projects/:id/worktrees`). */
export type WorktreeInfo = {
	/**  Node ID */
	node_id: NodeId,
	/**  Local path of the worktree */
	path: string,
	/**  Branch currently checked out */
	branch: string | null,
	/**  HEAD commit */
	head_commit: string | null,
	/**  Whether this is the main repository (not a worktree) */
	is_main: boolean,
};

/**  Specification of a worktree created together with the session. */
export type WorktreeSpec = {
	/**  Branch name */
	branch: string,
	/**  Base branch */
	base_branch: string | null,
};

/**  `GET /api/v1/projects/:id/worktrees` response. */
export type WorktreesResponse = {
	/**  Worktrees */
	worktrees: WorktreeInfo[],
};
